    }

    private static void AnalyzeMethod(SyntaxNodeAnalysisContext context)
    {
        var method = (MethodDeclarationSyntax)context.Node;

        // 方法已标 [EffectOverride] / [AcceptDeviation] ⇒ 逃逸通道已声明，跳过 DO-9 / A3 / A4 近似（§8.3）。
