    // 单条 API 内部的多态 Claim（如 AddChild 含 Write+Occupy、Load 含两次 Occupy(Create)）不报（见类注释护栏）。
    private static void AnalyzeKindMixAndCompat(SyntaxNodeAnalysisContext context, MethodDeclarationSyntax method,
