    {
        // 归一资源 → 跨调用 (kind,mode) 列表（同一 Invocation 内部的多个 Claim 仅贡献一次条目）
        var byResource = new Dictionary<ResourceId, List<(Kind Kind, Mode Mode)>>();
        var resourceLabel = new Dictionary<ResourceId, string>();

        foreach (var inv in invocations)
        {
            var m = FindWhitelistEntry(inv);
            if (m is null) continue;

            // 同站点去重：本调用贡献的 (kind,mode) 集合（按（kind,mode）去重，避免单 API 内部重复 Claim 计入）
            var siteClaims = m.Value.Claims
                .Select(c => (c.Kind, c.Mode))
                .Distinct()
                .ToArray();

            foreach (var (kind, mode) in siteClaims)
            {
                var key = ResourceId.Normalize(m.Value.Claims.First(c => c.Kind == kind && c.Mode == mode).Resource);
                if (!byResource.ContainsKey(key))
                {
                    byResource[key] = new List<(Kind, Mode)>();
                    resourceLabel[key] = m.Value.GodotApi;
                }
                byResource[key].Add((kind, mode));
            }
        }

        foreach (var kv in byResource)
        {
            var kinds = kv.Value.Select(x => x.Kind).ToImmutableHashSet();
            var modes = kv.Value.Select(x => x.Mode).ToImmutableHashSet();

            // A3 KIND_MIX：跨调用 kind 集合大小 >1 ⇒ 同资源混用多类效应（§3.1.4b DO-7）。
            if (kinds.Count > 1)
            {
                var kindList = string.Join(",", kinds.Select(k => k.ToString()));
