                foreach (var b in modes)
                {
                    if (!Compatible.IsCompatible(a, b))
                    {
                        conflict = true;
                        conflictPair = $"{a}+{b}";
                        break;
                    }
                }
            if (conflict)
            {
                context.ReportDiagnostic(Diagnostic.Create(
                    CompatConflictOnSameResource,
                    method.Identifier.GetLocation(),
                    method.Identifier.Text,
                    resourceLabel[kv.Key],
                    conflictPair));
            }
        }
    }

